    17	    public static String formatReceipt(Reservation reservation, Room room) {
    18	        StringBuilder sb = new StringBuilder();
    19	        GuestIdentification id = reservation.getIdentification();
    20	
    21	        sb.append(String.format("Comprovante de reserva nº %d%n", reservation.getId()));
