    23	            reservation.getGuestName(), id.getGuestCpf()));
    24	        sb.append(String.format("Quarto: %s (%s)%n",
    25	            reservation.getRoomNumber(), room.getType()));
    26	        sb.append(formatCheckInOut(reservation.getCheckIn(), reservation.getCheckOut(),
    27	            reservation.getNights(), "pt"));
    28	        sb.append(String.format("Diárias: %s%n", formatMoney(reservation.getSubtotal(), "pt")));
    29	
    30	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    31	            sb.append(String.format("Desconto: %s%n", formatMoney(reservation.getDiscount(), "pt")));
    32	        }
    33	
    34	        sb.append(String.format("Total: %s", formatMoney(reservation.getTotal(), "pt")));
    35	
    36	        return sb.toString();
    37	    }
