    75	            reservation.getNights(), "en"));
    76	        sb.append(String.format("Nights: %s%n", formatMoney(reservation.getSubtotal(), "en")));
    77	
    78	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    79	            sb.append(String.format("Discount: %s%n", formatMoney(reservation.getDiscount(), "en")));
