    87	    private static String formatCheckInOut(LocalDate checkIn, LocalDate checkOut, int nights, String lang) {
    88	        String checkInStr, checkOutStr, nightsLabel;
    89	
    90	        if ("en".equals(lang)) {
    91	            checkInStr = checkIn.format(EN_DATE_FORMAT);
    92	            checkOutStr = checkOut.format(EN_DATE_FORMAT);
    93	            nightsLabel = nights == 1 ? "1 night" : nights + " nights";
    94	        } else {
    95	            checkInStr = checkIn.format(PT_DATE_FORMAT);
    96	            checkOutStr = checkOut.format(PT_DATE_FORMAT);
    97	            nightsLabel = nights == 1 ? "1 diária" : nights + " diárias";
    98	        }
    99	
   100	        if ("en".equals(lang)) {
   101	            return String.format("Check-in: %s | Check-out: %s | %s%n",
   102	                checkInStr, checkOutStr, nightsLabel);
   103	        } else {
   104	            return String.format("Entrada: %s | Saída: %s | %s%n",
   105	                checkInStr, checkOutStr, nightsLabel);
   106	        }
   107	    }
   108	
   109	    private static String formatMoney(BigDecimal amount, String lang) {
   110	        if ("en".equals(lang)) {
   111	            return String.format(Locale.US, "BRL %,.2f", amount);
   112	        } else {
   113	            String formatted = String.format(Locale.forLanguageTag("pt-BR"), "%.2f", amount);
   114	            formatted = formatted.replace('.', ',');
   115	            return "R$ " + formatted;
   116	        }
   117	    }
