     7	import java.math.BigDecimal;
     8	import java.time.LocalDate;
     9	import java.time.temporal.ChronoUnit;
    10	import java.util.*;
    11	import java.util.concurrent.atomic.AtomicLong;
    12	
    13	public class ReservationService {
    14	    private final Map<Long, Reservation> reservations = new HashMap<>();
    15	    private final AtomicLong nextId = new AtomicLong(1);
    16	    private final RoomService roomService;
    17	    private final MessageService messageService;
    18	
    19	    public ReservationService(RoomService roomService, MessageService messageService) {
    20	        this.roomService = roomService;
    21	        this.messageService = messageService;
    22	    }
    23	
    24	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    25	                                        GuestIdentification identification, LocalDate checkIn,
    26	                                        LocalDate checkOut, int guests, RatePlan ratePlan) {
    27	        Room room = roomService.getRoomByNumber(roomNumber)
    28	            .orElseThrow(() -> new ServiceException("ROOM_NOT_FOUND", "Room not found", 404));
    29	
    30	        if (guests > room.getCapacity()) {
    31	            throw new ServiceException("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity", 422);
    32	        }
    33	
    34	        if (guests < 1) {
    35	            throw new ServiceException("INVALID_REQUEST", "Number of guests must be at least 1", 400);
    36	        }
    37	
    38	        if (!checkOut.isAfter(checkIn)) {
    39	            throw new ServiceException("INVALID_REQUEST", "Check-out must be after check-in", 400);
    40	        }
    41	
    42	        if (isRoomUnavailable(roomNumber, checkIn, checkOut, null)) {
    43	            throw new ServiceException("ROOM_UNAVAILABLE", "Room is not available for the selected dates", 409);
    44	        }
    45	
    46	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    47	        BigDecimal subtotal = PriceCalculator.calculateSubtotal(room, checkIn, checkOut);
    48	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, ratePlan);
    49	        BigDecimal total = PriceCalculator.round(subtotal.subtract(discount));
    50	
    51	        Reservation reservation = new Reservation(
    52	            nextId.getAndIncrement(),
    53	            roomNumber,
    54	            guestName,
    55	            guestEmail,
    56	            identification,
    57	            checkIn,
    58	            checkOut,
    59	            guests,
    60	            ratePlan,
    61	            nights,
    62	            subtotal,
    63	            discount,
    64	            total
    65	        );
    66	
    67	        reservations.put(reservation.getId(), reservation);
    68	        return reservation;
    69	    }
    70	
    71	    public Optional<Reservation> getReservation(long id) {
    72	        return Optional.ofNullable(reservations.get(id));
    73	    }
    74	
    75	    public Reservation confirmReservation(long id) {
    76	        Reservation reservation = getReservation(id)
    77	            .orElseThrow(() -> new ServiceException("RESERVATION_NOT_FOUND", "Reservation not found", 404));
    78	
    79	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    80	            throw new ServiceException("OPERATION_NOT_ALLOWED",
    81	                "Can only confirm pending reservations", 409);
    82	        }
    83	
    84	        reservation.setStatus(ReservationStatus.CONFIRMED);
    85	        reservation.setAmountPaid(reservation.getTotal());
    86	
    87	        sendConfirmationEmail(reservation);
    88	
    89	        return reservation;
    90	    }
    91	
    92	    public Reservation cancelReservation(long id) {
    93	        Reservation reservation = getReservation(id)
    94	            .orElseThrow(() -> new ServiceException("RESERVATION_NOT_FOUND", "Reservation not found", 404));
    95	
    96	        if (reservation.getStatus() == ReservationStatus.CHECKED_IN ||
    97	            reservation.getStatus() == ReservationStatus.CHECKED_OUT ||
    98	            reservation.getStatus() == ReservationStatus.CANCELLED) {
    99	            throw new ServiceException("OPERATION_NOT_ALLOWED",
   100	                "Cannot cancel reservation in current status", 409);
   101	        }
   102	
   103	        reservation.setStatus(ReservationStatus.CANCELLED);
   104	
   105	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
   106	            reservation.setRefund(reservation.getAmountPaid());
   107	        } else {
   108	            reservation.setRefund(BigDecimal.ZERO);
   109	        }
   110	
   111	        return reservation;
   112	    }
   113	
   114	    public Reservation checkIn(long id) {
   115	        Reservation reservation = getReservation(id)
   116	            .orElseThrow(() -> new ServiceException("RESERVATION_NOT_FOUND", "Reservation not found", 404));
   117	
   118	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
   119	            throw new ServiceException("OPERATION_NOT_ALLOWED",
   120	                "Can only check-in confirmed reservations", 409);
   121	        }
   122	
   123	        reservation.setStatus(ReservationStatus.CHECKED_IN);
   124	        return reservation;
   125	    }
   126	
   127	    public Document checkOut(long id) {
   128	        Reservation reservation = getReservation(id)
   129	            .orElseThrow(() -> new ServiceException("RESERVATION_NOT_FOUND", "Reservation not found", 404));
   130	
   131	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   132	            throw new ServiceException("OPERATION_NOT_ALLOWED",
   133	                "Can only check-out reservations that are checked in", 409);
   134	        }
   135	
   136	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   137	        return generateDocument(reservation);
   138	    }
   139	
   140	    public Document getDocument(long id) {
   141	        Reservation reservation = getReservation(id)
   142	            .orElseThrow(() -> new ServiceException("RESERVATION_NOT_FOUND", "Reservation not found", 404));
   143	
   144	        if (reservation.getStatus() == ReservationStatus.PENDING) {
   145	            throw new ServiceException("OPERATION_NOT_ALLOWED",
   146	                "Document only available for paid reservations", 409);
   147	        }
   148	
   149	        return generateDocument(reservation);
   150	    }
   151	
   152	    private Document generateDocument(Reservation reservation) {
   153	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber()).orElseThrow();
   154	        GuestIdentification id = reservation.getIdentification();
   155	
   156	        String title;
   157	        String text;
   158	
   159	        if (id.isCpf()) {
   160	            title = "Comprovante de reserva";
   161	            text = DocumentFormatter.formatReceipt(reservation, room);
   162	        } else if (id.isCompany()) {
   163	            title = "Fatura de hospedagem";
   164	            text = DocumentFormatter.formatInvoice(reservation, room);
   165	        } else {
   166	            title = "Booking receipt";
   167	            text = DocumentFormatter.formatBookingReceipt(reservation, room);
   168	        }
   169	
   170	        return new Document(
   171	            title,
   172	            reservation.getId(),
   173	            reservation.getGuestName(),
   174	            id.getGuestCpf(),
   175	            id.getCompanyCnpj(),
   176	            id.getCompanyName(),
   177	            id.getGuestPassport(),
   178	            id.getGuestCountry(),
   179	            reservation.getRoomNumber(),
   180	            room.getType(),
   181	            reservation.getCheckIn(),
   182	            reservation.getCheckOut(),
   183	            reservation.getNights(),
   184	            reservation.getSubtotal(),
   185	            reservation.getDiscount(),
   186	            reservation.getTotal(),
   187	            text
   188	        );
   189	    }
   190	
   191	    private void sendConfirmationEmail(Reservation reservation) {
   192	        Document document = generateDocument(reservation);
   193	        String emailBody = DocumentFormatter.formatConfirmationEmail(
   194	            reservation.getGuestName(),
   195	            document.getText()
   196	        );
   197	
   198	        messageService.sendEmail(
   199	            reservation.getGuestEmail(),
   200	            "Reserva confirmada - Pousada Maré Alta",
   201	            emailBody
   202	        );
   203	    }
   204	
   205	    private boolean isRoomUnavailable(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeReservationId) {
   206	        return reservations.values().stream()
   207	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
   208	            .filter(r -> excludeReservationId == null || r.getId() != excludeReservationId)
   209	            .filter(r -> r.getRoomNumber().equals(roomNumber))
   210	            .anyMatch(r -> datesOverlap(checkIn, checkOut, r.getCheckIn(), r.getCheckOut()));
   211	    }
   212	
   213	    private boolean datesOverlap(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
   214	        return start1.isBefore(end2) && start2.isBefore(end1);
   215	    }
   216	
   217	    public List<Reservation> getAllReservations() {
   218	        return List.copyOf(reservations.values());
   219	    }
   220	}
