    10	import java.util.*;
    11	import java.util.concurrent.atomic.AtomicLong;
    12	
    13	public class ReservationService {
    14	    private final Map<Long, Reservation> reservations = new HashMap<>();
    15	    private final AtomicLong nextId = new AtomicLong(1);
    16	    private final RoomService roomService;
    17	    private final MessageService messageService;
    18	
    19	    public ReservationService(RoomService roomService, MessageService messageService) {
    20	        this.roomService = roomService;
    21	        this.messageService = messageService;
    22	    }
    23	
    24	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    25	                                        GuestIdentification identification, LocalDate checkIn,
    26	                                        LocalDate checkOut, int guests, RatePlan ratePlan) {
    27	        Room room = roomService.getRoomByNumber(roomNumber)
    28	            .orElseThrow(() -> new ServiceException("ROOM_NOT_FOUND", "Room not found", 404));
    29	
    30	        if (guests > room.getCapacity()) {
    31	            throw new ServiceException("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity", 422);
    32	        }
    33	
    34	        if (guests < 1) {
    35	            throw new ServiceException("INVALID_REQUEST", "Number of guests must be at least 1", 400);
    36	        }
    37	
    38	        if (!checkOut.isAfter(checkIn)) {
    39	            throw new ServiceException("INVALID_REQUEST", "Check-out must be after check-in", 400);
    40	        }
    41	
    42	        if (isRoomUnavailable(roomNumber, checkIn, checkOut, null)) {
    43	            throw new ServiceException("ROOM_UNAVAILABLE", "Room is not available for the selected dates", 409);
    44	        }
    45	
    46	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    47	        BigDecimal subtotal = PriceCalculator.calculateSubtotal(room, checkIn, checkOut);
    48	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, ratePlan);
    49	        BigDecimal total = PriceCalculator.round(subtotal.subtract(discount));
    50	
    51	        Reservation reservation = new Reservation(
    52	            nextId.getAndIncrement(),
    53	            roomNumber,
    54	            guestName,
    55	            guestEmail,
    56	            identification,
    57	            checkIn,
    58	            checkOut,
    59	            guests,
    60	            ratePlan,
    61	            nights,
    62	            subtotal,
    63	            discount,
    64	            total
    65	        );
    66	
    67	        reservations.put(reservation.getId(), reservation);
    68	        return reservation;
    69	    }
    70	
    71	    public Optional<Reservation> getReservation(long id) {
    72	        return Optional.ofNullable(reservations.get(id));
    73	    }
    74	
    75	    public Reservation confirmReservation(long id) {
    76	        Reservation reservation = getReservation(id)
    77	            .orElseThrow(() -> new ServiceException("RESERVATION_NOT_FOUND", "Reservation not found", 404));
    78	
    79	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    80	            throw new ServiceException("OPERATION_NOT_ALLOWED",
    81	                "Can only confirm pending reservations", 409);
    82	        }
    83	
    84	        reservation.setStatus(ReservationStatus.CONFIRMED);
    85	        reservation.setAmountPaid(reservation.getTotal());
    86	
    87	        sendConfirmationEmail(reservation);
