   152	    private Document generateDocument(Reservation reservation) {
   153	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber()).orElseThrow();
   154	        GuestIdentification id = reservation.getIdentification();
   155	
   156	        String title;
   157	        String text;
   158	
   159	        if (id.isCpf()) {
