   161	            text = DocumentFormatter.formatReceipt(reservation, room);
   162	        } else if (id.isCompany()) {
   163	            title = "Fatura de hospedagem";
   164	            text = DocumentFormatter.formatInvoice(reservation, room);
   165	        } else {
