   174	            id.getGuestCpf(),
   175	            id.getCompanyCnpj(),
   176	            id.getCompanyName(),
   177	            id.getGuestPassport(),
   178	            id.getGuestCountry(),
   179	            reservation.getRoomNumber(),
   180	            room.getType(),
   181	            reservation.getCheckIn(),
   182	            reservation.getCheckOut(),
   183	            reservation.getNights(),
   184	            reservation.getSubtotal(),
   185	            reservation.getDiscount(),
   186	            reservation.getTotal(),
