    21	    public void createReservation(Context ctx) {
    22	        try {
    23	            JsonNode json = ctx.bodyAsClass(JsonNode.class);
    24	
    25	            if (!json.has("roomNumber") || !json.has("guestName") || !json.has("guestEmail") ||
    26	                !json.has("checkIn") || !json.has("checkOut") || !json.has("guests") ||
    27	                !json.has("ratePlan")) {
    28	                throw new ServiceException("INVALID_REQUEST", "Missing required fields", 400);
    29	            }
    30	
    31	            String roomNumber = json.get("roomNumber").asText();
    32	            String guestName = json.get("guestName").asText();
    33	            String guestEmail = json.get("guestEmail").asText();
    34	            LocalDate checkIn = LocalDate.parse(json.get("checkIn").asText());
    35	            LocalDate checkOut = LocalDate.parse(json.get("checkOut").asText());
    36	            int guests = json.get("guests").asInt();
    37	            RatePlan ratePlan = RatePlan.valueOf(json.get("ratePlan").asText());
    38	
    39	            GuestIdentification identification = parseIdentification(json);
    40	
    41	            Reservation reservation = reservationService.createReservation(
    42	                roomNumber, guestName, guestEmail, identification,
    43	                checkIn, checkOut, guests, ratePlan
    44	            );
    45	
    46	            ctx.status(201).json(toDto(reservation));
    47	        } catch (DateTimeParseException e) {
    48	            throw new ServiceException("INVALID_REQUEST", "Invalid date format", 400);
    49	        } catch (IllegalArgumentException e) {
    50	            throw new ServiceException("INVALID_REQUEST", "Invalid field value", 400);
    51	        }
    52	    }
    53	
    54	    private GuestIdentification parseIdentification(JsonNode json) {
    55	        boolean hasCpf = json.has("guestCpf") && !json.get("guestCpf").isNull();
    56	        boolean hasCnpj = json.has("companyCnpj") && !json.get("companyCnpj").isNull();
    57	        boolean hasCompanyName = json.has("companyName") && !json.get("companyName").isNull();
    58	        boolean hasPassport = json.has("guestPassport") && !json.get("guestPassport").isNull();
    59	        boolean hasCountry = json.has("guestCountry") && !json.get("guestCountry").isNull();
    60	
    61	        int identificationCount = 0;
    62	        if (hasCpf) identificationCount++;
    63	        if (hasCnpj && hasCompanyName) identificationCount++;
    64	        if (hasPassport && hasCountry) identificationCount++;
    65	
    66	        if (identificationCount != 1) {
    67	            throw new ServiceException("INVALID_REQUEST",
    68	                "Must provide exactly one type of identification", 400);
    69	        }
    70	
    71	        if (hasCpf) {
    72	            return GuestIdentification.withCpf(json.get("guestCpf").asText());
    73	        } else if (hasCnpj && hasCompanyName) {
    74	            return GuestIdentification.withCompany(
    75	                json.get("companyCnpj").asText(),
    76	                json.get("companyName").asText()
    77	            );
    78	        } else {
    79	            return GuestIdentification.withPassport(
    80	                json.get("guestPassport").asText(),
    81	                json.get("guestCountry").asText()
    82	            );
    83	        }
    84	    }
