    10	import java.time.format.DateTimeFormatter;
    11	import java.util.Comparator;
    12	import java.util.List;
    13	import java.util.Locale;
    14	import java.util.stream.Collectors;
    15	
    16	public class ReportService {
    17	    private final ReservationService reservationService;
    18	    private final RoomService roomService;
    19	
    20	    public ReportService(ReservationService reservationService, RoomService roomService) {
    21	        this.reservationService = reservationService;
    22	        this.roomService = roomService;
    23	    }
    24	
    25	    public String generateOccupancyReport(LocalDate date) {
    26	        StringBuilder csv = new StringBuilder();
    27	        csv.append("room,type,reservation,check_in,check_out\n");
    28	
    29	        List<Reservation> occupiedReservations = reservationService.getAllReservations().stream()
    30	            .filter(r -> r.getStatus() == ReservationStatus.CONFIRMED ||
    31	                        r.getStatus() == ReservationStatus.CHECKED_IN ||
    32	                        r.getStatus() == ReservationStatus.CHECKED_OUT)
    33	            .filter(r -> !r.getCheckIn().isAfter(date) && r.getCheckOut().isAfter(date))
    34	            .sorted(Comparator.comparing(Reservation::getRoomNumber))
    35	            .toList();
    36	
    37	        for (Reservation reservation : occupiedReservations) {
    38	            Room room = roomService.getRoomByNumber(reservation.getRoomNumber()).orElseThrow();
    39	            csv.append(String.format("%s,%s,%d,%s,%s\n",
    40	                reservation.getRoomNumber(),
    41	                room.getType(),
    42	                reservation.getId(),
    43	                reservation.getCheckIn().format(DateTimeFormatter.ISO_LOCAL_DATE),
    44	                reservation.getCheckOut().format(DateTimeFormatter.ISO_LOCAL_DATE)
    45	            ));
    46	        }
    47	
    48	        int totalRooms = roomService.getAllRooms().size();
    49	        int occupiedRooms = occupiedReservations.size();
    50	        csv.append(String.format("total,%d/%d\n", occupiedRooms, totalRooms));
    51	
    52	        return csv.toString();
    53	    }
    54	
    55	    public String generateRevenueReport(YearMonth month) {
    56	        StringBuilder csv = new StringBuilder();
    57	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    58	
    59	        List<Reservation> relevantReservations = reservationService.getAllReservations().stream()
    60	            .filter(r -> YearMonth.from(r.getCheckIn()).equals(month))
    61	            .filter(r -> r.getAmountPaid().compareTo(BigDecimal.ZERO) > 0 ||
    62	                        (r.getRefund() != null && r.getRefund().compareTo(r.getAmountPaid()) < 0))
    63	            .sorted(Comparator.comparing(Reservation::getCheckIn)
    64	                .thenComparing(Reservation::getId))
    65	            .toList();
    66	
    67	        BigDecimal totalRevenue = BigDecimal.ZERO;
    68	
    69	        for (Reservation reservation : relevantReservations) {
    70	            BigDecimal revenue = reservation.getAmountPaid();
    71	            if (reservation.getRefund() != null) {
    72	                revenue = revenue.subtract(reservation.getRefund());
    73	            }
    74	
    75	            csv.append(String.format(Locale.US, "%d,%s,%s,%s,%s,%.2f\n",
    76	                reservation.getId(),
    77	                reservation.getRoomNumber(),
    78	                reservation.getCheckIn().format(DateTimeFormatter.ISO_LOCAL_DATE),
    79	                reservation.getCheckOut().format(DateTimeFormatter.ISO_LOCAL_DATE),
    80	                reservation.getStatus(),
    81	                revenue
    82	            ));
    83	
    84	            totalRevenue = totalRevenue.add(revenue);
    85	        }
    86	
    87	        csv.append(String.format(Locale.US, "total,%.2f\n", totalRevenue));
    88	
    89	        return csv.toString();
    90	    }
    91	}
