     6	import java.math.BigDecimal;
     7	import java.math.RoundingMode;
     8	import java.time.LocalDate;
     9	
    10	public class PriceCalculator {
    11	
    12	    public static BigDecimal calculateNightlyPrice(Room room, LocalDate date) {
    13	        BigDecimal baseRate = room.getNightlyRate();
    14	        if (isHighSeason(date)) {
    15	            BigDecimal multiplier = new BigDecimal("1.20");
    16	            return round(baseRate.multiply(multiplier));
    17	        }
    18	        return baseRate;
    19	    }
    20	
    21	    public static BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
    22	        BigDecimal subtotal = BigDecimal.ZERO;
    23	        LocalDate current = checkIn;
    24	
    25	        while (current.isBefore(checkOut)) {
    26	            BigDecimal nightlyPrice = calculateNightlyPrice(room, current);
    27	            subtotal = subtotal.add(nightlyPrice);
    28	            current = current.plusDays(1);
    29	        }
    30	
    31	        return round(subtotal);
    32	    }
    33	
    34	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    35	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    36	            BigDecimal discountRate = new BigDecimal("0.15");
    37	            return round(subtotal.multiply(discountRate));
    38	        }
    39	        return BigDecimal.ZERO;
    40	    }
    41	
    42	    public static BigDecimal calculateIss(BigDecimal total) {
    43	        BigDecimal issRate = new BigDecimal("0.05");
    44	        return round(total.multiply(issRate));
    45	    }
    46	
    47	    public static BigDecimal round(BigDecimal value) {
    48	        return value.setScale(2, RoundingMode.HALF_EVEN);
    49	    }
    50	
    51	    private static boolean isHighSeason(LocalDate date) {
    52	        int month = date.getMonthValue();
    53	        int day = date.getDayOfMonth();
    54	
    55	        // Julho inteiro
    56	        if (month == 7) {
    57	            return true;
    58	        }
    59	
    60	        // 15/12 até fim de fevereiro
    61	        if (month == 12 && day >= 15) {
    62	            return true;
    63	        }
    64	
    65	        if (month == 1 || month == 2) {
    66	            return true;
    67	        }
    68	
    69	        return false;
    70	    }
    71	}

